(()=>{'use strict';const books=ScienceVideos,guides=VideoGuides,objectives=Object.fromEntries(ObjectiveCourse.map(q=>[q.id,q])),root=document.querySelector('#watchLearn'),titles={genetics:'Genetics & cell division',evolution:'Evolution',rates:'Reaction rates',heat:'Heat transfer'},esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected='genetics';const answers=new Map(),opened=new Set();
const forTopic=id=>books.filter(b=>b.topic===id),count=id=>forTopic(id).reduce((n,b)=>n+b.videos.length,0),time=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
function inline(id){return `<section class="watch-inline" aria-label="Watch and learn for ${titles[id]}"><div><h4>Watch &amp; learn</h4><p>${count(id)} videos · objective tags, focused timestamps and quick checks.</p></div><button data-watch-topic="${id}">Choose a video ↗</button></section>`;}
function feedback(id){const a=answers.get(id),g=guides[id];return a===undefined?'':`${a===g.correct?'Correct.':'Not quite.'} ${esc(g.feedback)}`;}
function card(v){const g=guides[v.id],a=answers.get(v.id);return `<article class="watch-video" aria-labelledby="video-${v.id}"><a class="watch-video-link" href="${v.url}" target="_blank" rel="noopener noreferrer"><span class="watch-play" aria-hidden="true">▶</span><span><small>${esc(v.kind)}</small><strong id="video-${v.id}">${esc(v.label)}</strong><span class="watch-source">Open full video on YouTube ↗</span></span></a><div class="watch-guide"><div class="watch-objectives" aria-label="Related learning objectives">${g.objectiveIds.map(id=>{const o=objectives[id];return `<button type="button" data-open-objective="${id}">${id} · ${esc(o.title)}${o.level==='extension'?' · EXT':''}</button>`}).join('')}</div><p class="watch-focus"><b>Focus while watching</b>${esc(g.focus)}</p><div class="watch-timestamps" aria-label="Jump to an explanation">${g.segments.map(s=>`<a href="${esc(v.url)}&amp;t=${s.start}s" target="_blank" rel="noopener noreferrer"><time>${time(s.start)}</time><span>${esc(s.label)} ↗</span></a>`).join('')}</div>${g.note?`<p class="watch-note">${esc(g.note)}</p>`:''}<form class="watch-check" data-video-check="${v.id}"><fieldset><legend><small>PAUSE &amp; CHECK</small>${esc(g.question)}</legend>${g.options.map((option,i)=>`<label><input type="radio" name="watch-${v.id}" value="${i}" ${a===i?'checked':''} required><span>${esc(option)}</span></label>`).join('')}</fieldset><button type="submit">Check answer</button><p class="watch-feedback" role="status" aria-live="polite">${feedback(v.id)}</p></form></div></article>`;}
function render(){root.innerHTML=`<div class="sectionhead"><div><p class="eyebrow">WATCH WITH A PURPOSE</p><h2>Watch &amp; learn.</h2></div><span class="pill">58 GUIDED VIDEOS</span></div><p>Pick a video, read its focus prompt, then jump to an explanation. Return here for a quick check. Objective tags open the matching learning activity; EXT marks extension learning.</p><div class="watch-topics" aria-label="Choose video topic">${Object.entries(titles).map(([id,name])=>`<button data-watch-select="${id}" aria-pressed="${id===selected}">${name}<span>${count(id)} videos</span></button>`).join('')}</div><div id="watchTopic"><h3 tabindex="-1" id="watchHeading">${titles[selected]}</h3>${forTopic(selected).map(b=>`<details class="watch-book" data-video-book="${b.id}" ${opened.has(b.id)?'open':''}><summary><span>${b.section?`<small>${esc(b.section)}</small>`:''}<strong>${esc(b.title)}</strong>${b.extension?'<em>Extension</em>':''}</span><span>${b.videos.length} videos +</span></summary><div class="watch-links">${b.videos.map(card).join('')}</div></details>`).join('')}<div class="watch-return"><button data-watch-model="${selected}">Explore the model →</button><button data-watch-quiz="${selected}">Practise this topic →</button></div><p class="small">Jump points checked against YouTube chapters or captions on 4 November 2026. Links open YouTube in a new tab; playback continues beyond the suggested section. Quick checks are rehearsal and stay available during this visit. Use objective practice for tracked progress; watching does not mark an objective complete.</p></div>`;
root.querySelectorAll('[data-video-book]').forEach(d=>d.addEventListener('toggle',()=>d.open?opened.add(d.dataset.videoBook):opened.delete(d.dataset.videoBook)));root.querySelectorAll('[data-watch-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.watchSelect;render()});root.querySelector('[data-watch-model]').onclick=()=>window.dispatchEvent(new CustomEvent('science-model-topic',{detail:selected}));root.querySelector('[data-watch-quiz]').onclick=()=>window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:selected}));}
root.addEventListener('submit',e=>{const form=e.target.closest('[data-video-check]');if(!form)return;e.preventDefault();const choice=form.querySelector('input:checked');if(!choice)return;answers.set(form.dataset.videoCheck,Number(choice.value));form.querySelector('.watch-feedback').innerHTML=feedback(form.dataset.videoCheck);});
function open(id){if(!titles[id])return;selected=id;render();root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});root.querySelector('#watchHeading').focus({preventScroll:true});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-watch-topic]');if(b)open(b.dataset.watchTopic)});window.addEventListener('science-watch-topic',e=>open(e.detail));window.WatchLearn={inline,count};render();
})();
